class Solution:
    def kthOrdering(self, n: int, k: int) -> str:
        a = list(range(1, n + 1))
        for _ in range(k - 1):
            i = n - 2
            while a[i] > a[i + 1]:
                i -= 1
            j = n - 1
            while a[j] < a[i]:
                j -= 1
            a[i], a[j] = a[j], a[i]
            a[i + 1:] = reversed(a[i + 1:])
        return "".join(map(str, a))

