function kthOrdering(n: number, k: number): string {
  const fact = [1];
  for (let i = 1; i < n; i++) fact[i] = fact[i - 1] * i;
  const digits = Array.from({ length: n }, (_, i) => i + 1);
  let idx = k - 1, out = "";
  for (let i = n - 1; i >= 0; i--) {
    const pos = Math.floor(idx / fact[i]);
    out += digits[pos];
    digits.splice(pos, 1);
    idx %= fact[i];
  }
  return out;
}

